const SCRIPT: Plan = {"base":{"street":[1250,875,875],"wangan":[900,900,1200],"touge":[1200,950,850]},"splits":{"street":{"P1":[100,0,0],"P2":[100,0,0],"H1":[40,60,0],"E1":[40,0,60]},"wangan":{"P1":[60,0,40],"H1":[0,60,40],"E1":[0,0,100],"E2":[0,0,100]},"touge":{"P1":[100,0,0],"H1":[20,60,20],"E1":[30,0,70],"E2":[30,0,70]}},"grinds":{"R1 mat1":3,"R1 boss":10,"R2 kid1":7,"R2 boss":6,"R3 mat1":5,"R3 boss":7},"buys":[{"at":"R1 kid1","phase":"pre","key":"P1"},{"at":"R1 kid1","phase":"post","key":"P1"},{"at":"R1 kid1","phase":"post","key":"P2"},{"at":"R1 kid2","phase":"post","key":"H1"},{"at":"R1 kid2","phase":"post","key":"E1"},{"at":"R1 kid2","phase":"post","key":"E1"},{"at":"R2 kid1","phase":"pre","key":"P1"},{"at":"R2 kid1","phase":"pre","key":"H1"},{"at":"R2 kid1","phase":"pre","key":"E1"},{"at":"R2 kid1","phase":"pre","key":"E2"},{"at":"R3 kid1","phase":"pre","key":"P1"},{"at":"R3 kid1","phase":"pre","key":"H1"},{"at":"R3 kid1","phase":"pre","key":"E1"},{"at":"R3 kid1","phase":"pre","key":"E2"}],"pickG":{"R1 mat1":"E1","R1 boss":"E1","R2 kid1":"E1","R2 boss":"H1","R3 mat1":"E2","R3 boss":"E2"},"pickW":{"R1 kid1":"P1","R1 kid2":"P2","R1 mat1":"H1","R1 mat2":"E1","R1 oh2":"P2","R1 boss":"H1","R2 kid1":"E2","R2 kid2":"E1","R2 mat1":"P1","R2 mat2":"H1","R2 oh1":"E2","R2 oh2":"E1","R2 boss":"P1","R3 kid1":"P1","R3 kid2":"E1","R3 mat1":"H1","R3 mat2":"E2","R3 oh1":"P1","R3 oh2":"E1","R3 boss":"H1"}};
const PY_MAIN: [string, number, number, number | null, number, number][] = [["R1 kid1",3000,1.0195,23.7,50.0,15350.0],["R1 kid2",3145.0,1.0323,42.1,100.0,14700.0],["R1 mat1",3299.8,1.0233,39.2,1552.5,12002.5],["R1 mat2",3326.7,1.009,26.7,2427.5,10377.5],["R1 oh1",3351.8,1.011,32.7,3302.5,8752.5],["R1 oh2",3351.8,1.0043,30.2,4177.5,7127.5],["R1 boss",3508.6,1.0374,91.5,10550.0,0.0],["R2 kid1",3504.0,1.0228,45.6,13887.5,0.0],["R2 kid2",3640.2,1.0445,70.1,15037.5,0.0],["R2 mat1",3751.9,1.0302,55.4,17912.5,0.0],["R2 mat2",3839.6,1.0258,53.4,20787.5,0.0],["R2 oh1",3899.7,1.0225,53.0,23662.5,0.0],["R2 oh2",3929.2,1.0254,59.7,26537.5,0.0],["R2 boss",4044.0,1.0548,91.6,39532.5,0.0],["R3 kid1",4044.0,1.0328,16.3,37042.5,0.0],["R3 kid2",4143.6,1.0412,25.2,38392.5,0.0],["R3 mat1",4315.9,1.0556,50.1,45480.0,0.0],["R3 mat2",4368.1,1.0353,33.0,48855.0,0.0],["R3 oh1",4437.6,1.0345,35.7,52230.0,0.0],["R3 oh2",4507.2,1.043,48.2,55605.0,0.0],["R3 boss",4628.0,1.0702,91.1,71602.5,0.0]];

const DNAME: Record<string, string> = { street: "Street", wangan: "Wangan", touge: "Touge" };
const RUNG_NAME: Record<string, string> = { kid1: "Kid 1", kid2: "Kid 2", mat1: "Mature 1", mat2: "Mature 2", oh1: "Old head 1", oh2: "Old head 2", boss: "Boss" };
const MOD_NAME: Record<string, string> = { P1: "POW mod 1", P2: "POW mod 2", H1: "HAN mod", E1: "EN mod 1", E2: "EN mod 2" };
const STATN = ["POW", "HAN", "EN"];
const money = (x: number) => "$" + Math.round(x).toLocaleString("en-US");
const moneyS = (x: number) => (x > 0.005 ? "+" : x < -0.005 ? "−" : "") + money(Math.abs(x));
const pc = (x: number | null) => (x === null ? "—" : x.toFixed(1) + "%");
const toneOf = (w: number): "success" | "warning" | "danger" => (w >= 60 ? "success" : w >= 50 ? "warning" : "danger");
const raceName = (id: string) => { const p = id.split(" "); return p[0] + " " + RUNG_NAME[p[1]]; };
const EMPTY3 = (): string[] => ["", "", ""];
function toNums(a: string[] | undefined): number[] | null {
  if (!a || a.some((x) => x.trim() === "")) return null;
  const v = a.map((x) => Number(x));
  return v.some((x) => !isFinite(x)) ? null : v;
}
function baseIssue(a: string[]): string | null {
  const v = toNums(a);
  if (!v) return "Not set: enter all three stats";
  const s = v[0] + v[1] + v[2];
  if (Math.abs(s - C.STOCK_TOTAL) > 1e-9) return "Adds to " + s.toLocaleString("en-US") + "; must be 3,000";
  if (v.some((x) => x < C.BASE_MIN || x > C.BASE_MAX)) return "Each stat must be 750–1,500 (25–50% of 3,000)";
  return null;
}
function splitIssue(k: string, a: string[] | undefined): string | null {
  const v = toNums(a);
  if (!v) return "Not set";
  if (Math.min(v[0], v[1], v[2]) < 0) return "No negative shares";
  if (Math.abs(v[0] + v[1] + v[2] - 100) > 1e-9) return "Adds to " + (v[0] + v[1] + v[2]) + "%; must be 100%";
  if (v[SI[k[0]]] < 100 * C.OWN_MIN - 1e-9) return STATN[SI[k[0]]] + " must be at least 60%";
  return null;
}

// Keep the clicked control still: a re-render remounts tables and updates Metrics / LineChart
// and the inspector, which otherwise jumps the scroll. Pin any click on a [data-pin] node.
const pinId = (id: string) => "pin-" + id.replace(/\s+/g, "-");
type ScrollPin = { id: string; y: number; spots: { top: number; left: number; set: (t: number, l: number) => void }[] };
function pinNode(id: string): HTMLElement | null {
  return typeof document === "undefined" ? null : document.getElementById(id);
}
function scrollSpots(from: Element | null): ScrollPin["spots"] {
  const spots: ScrollPin["spots"] = [];
  const seen = new Set<Element | Window>();
  const addWin = () => {
    if (seen.has(window)) return;
    seen.add(window);
    spots.push({ top: window.scrollY, left: window.scrollX, set: (t, l) => window.scrollTo(l, t) });
  };
  const addEl = (node: Element) => {
    if (seen.has(node)) return;
    seen.add(node);
    const el = node as HTMLElement;
    spots.push({ top: el.scrollTop, left: el.scrollLeft, set: (t, l) => { el.scrollTop = t; el.scrollLeft = l; } });
  };
  addWin();
  let n: Element | null = from;
  while (n) {
    const st = getComputedStyle(n);
    if (/(auto|scroll|overlay)/.test(st.overflowY) || /(auto|scroll|overlay)/.test(st.overflowX)) addEl(n);
    n = n.parentElement;
  }
  return spots;
}
function capturePin(id: string, ev?: any): ScrollPin {
  const t: Element | null = ev && ev.currentTarget ? ev.currentTarget : ev && ev.target ? ev.target : null;
  const node: Element | null = (t && t.closest ? t.closest("[data-pin]") : null) || pinNode(id);
  return { id, y: node ? node.getBoundingClientRect().top : 0, spots: scrollSpots(node || t) };
}
function applyPin(pin: ScrollPin, node?: Element | null) {
  const el = node || pinNode(pin.id);
  for (const s of pin.spots) s.set(s.top, s.left);
  if (!el) return;
  const nudge = () => {
    const dy = el.getBoundingClientRect().top - pin.y;
    if (Math.abs(dy) < 1) return false;
    let n: Element | null = el.parentElement; let used = false;
    while (n) {
      const st = getComputedStyle(n);
      if (/(auto|scroll|overlay)/.test(st.overflowY) && (n as HTMLElement).scrollHeight > (n as HTMLElement).clientHeight + 1) {
        (n as HTMLElement).scrollTop += el.getBoundingClientRect().top - pin.y; used = true;
      }
      n = n.parentElement;
    }
    const dy2 = el.getBoundingClientRect().top - pin.y;
    if (Math.abs(dy2) >= 1) window.scrollBy(0, dy2);
    return used || Math.abs(dy2) >= 1;
  };
  nudge();
}

export default function ModSkillPlanner() {
  const theme = useGrokTheme();
  const [base, setBase] = useState<Record<string, string[]>>({ street: EMPTY3(), wangan: EMPTY3(), touge: EMPTY3() });
  const [splits, setSplits] = useState<Record<string, Record<string, string[]>>>({ street: {}, wangan: {}, touge: {} });
  const [grinds, setGrinds] = useState<Record<string, number>>({});
  const [buys, setBuys] = useState<Buy[]>([]);
  const [pickG, setPickG] = useState<Record<string, string>>({});
  const [pickW, setPickW] = useState<Record<string, string>>({});
  const [sel, setSel] = useState<string>("R1 kid1");
  const [shopKey, setShopKey] = useState<string>("P1");
  const [shopPhase, setShopPhase] = useState<string>("post");

  const planSplits: Record<string, Record<string, number[]>> = {};
  for (const d of C.ROUNDS as string[]) {
    planSplits[d] = {};
    for (const k of Object.keys(splits[d])) { const v = toNums(splits[d][k]); if (v) planSplits[d][k] = v; }
  }
  const plan: Plan = {
    base: { street: toNums(base.street), wangan: toNums(base.wangan), touge: toNums(base.touge) },
    splits: planSplits, grinds, buys, pickG, pickW,
  };
  const key = JSON.stringify(plan);
  const rows = useMemo(() => simulate(plan), [key]);
  const ver = useMemo(() => {
    const s = simulate(SCRIPT);
    let worstPts = 0, worstR = 0, worstWin = 0, worstCash = 0, same = 0;
    PY_MAIN.forEach((p, i) => {
      const x = s[i];
      const dp = Math.abs(x.points - p[1]), dr = Math.abs(x.r - p[2]), dc = Math.max(Math.abs(x.cash - p[4]), Math.abs(x.debt - p[5]));
      const dw = p[3] === null || x.show === null ? (p[3] === x.show ? 0 : 999) : Math.abs(x.show - p[3]);
      worstPts = Math.max(worstPts, dp); worstR = Math.max(worstR, dr); worstWin = Math.max(worstWin, dw); worstCash = Math.max(worstCash, dc);
      if (dp < 0.051 && dr < 0.00006 && dw < 0.051 && dc < 0.006) same++;
    });
    return { worstPts, worstR, worstWin, worstCash, same, n: PY_MAIN.length, rows: s };
  }, []);

  const pinRef = useRef<ScrollPin | null>(null);
  const hold = (id: string, ev?: any) => { pinRef.current = capturePin(id, ev); };
  const attachPin = (id: string) => (el: HTMLDivElement | null) => {
    const p = pinRef.current;
    if (el && p && p.id === id) applyPin(p, el);
  };
  useEffect(() => {
    const arm = (ev: any) => {
      if (ev.type === "keydown" && ev.key !== "Enter" && ev.key !== " ") return;
      const t: Element | null = ev && ev.target ? ev.target : null;
      const node: Element | null = t && t.closest ? t.closest("[data-pin]") : null;
      const id = node && (node as HTMLElement).id ? (node as HTMLElement).id : "pin-page";
      pinRef.current = capturePin(id, ev);
    };
    document.addEventListener("pointerdown", arm, true);
    document.addEventListener("keydown", arm, true);
    return () => {
      document.removeEventListener("pointerdown", arm, true);
      document.removeEventListener("keydown", arm, true);
    };
  }, []);
  const viewKey = [key, sel, shopKey, shopPhase, JSON.stringify(base), JSON.stringify(splits)].join("|");
  useEffect(() => {
    const p = pinRef.current;
    if (!p) return;
    const run = () => { if (pinRef.current === p) applyPin(p); };
    run();
    const a = requestAnimationFrame(run);
    const b = requestAnimationFrame(() => requestAnimationFrame(run));
    const t = window.setTimeout(() => { run(); if (pinRef.current === p) pinRef.current = null; }, 160);
    return () => { cancelAnimationFrame(a); cancelAnimationFrame(b); window.clearTimeout(t); };
  }, [viewKey]);

  const idx = Math.max(0, rows.findIndex((r) => r.id === sel));
  const cur = rows[idx];
  const kit: string[] = C.KITS[cur.d];
  const press = (pid: string, ev: any, fn: () => void) => { if (ev && ev.preventDefault) ev.preventDefault(); hold(pid, ev); fn(); };
  const go = (i: number) => setSel(rows[Math.min(rows.length - 1, Math.max(0, i))].id);
  const setN = (id: string, n: number) => setGrinds({ ...grinds, [id]: Math.max(0, n) });
  const setB = (d: string, i: number, v: string) => { const a = base[d].slice(); a[i] = v; setBase({ ...base, [d]: a }); };
  const setS = (d: string, k: string, i: number, v: string) => {
    const a = (splits[d][k] || EMPTY3()).slice(); a[i] = v;
    setSplits({ ...splits, [d]: { ...splits[d], [k]: a } });
  };
  const isDefault = (
    Object.values(base).every((a) => a.every((x) => x === "")) && Object.values(splits).every((m) => Object.keys(m).length === 0)
    && Object.keys(grinds).every((k) => !grinds[k]) && buys.length === 0 && Object.keys(pickG).length === 0 && Object.keys(pickW).length === 0
    && sel === "R1 kid1"
  );
  const reset = () => {
    if (!isDefault && typeof window !== "undefined" && typeof window.confirm === "function") {
      if (!window.confirm("Reset the planner? This clears the base setup, splits, grinds, buys and XP picks.")) return;
    }
    setBase({ street: EMPTY3(), wangan: EMPTY3(), touge: EMPTY3() }); setSplits({ street: {}, wangan: {}, touge: {} });
    setGrinds({}); setBuys([]); setPickG({}); setPickW({}); setSel("R1 kid1"); setShopKey("P1"); setShopPhase("post");
  };
  const loadExample = () => {
    if (!isDefault && typeof window !== "undefined" && typeof window.confirm === "function") {
      if (!window.confirm("Replace all your choices with the verified example playthrough?")) return;
    }
    const sb: Record<string, string[]> = {}; const ss: Record<string, Record<string, string[]>> = {};
    for (const d of C.ROUNDS as string[]) {
      sb[d] = (SCRIPT.base[d] as number[]).map(String); ss[d] = {};
      for (const k of Object.keys(SCRIPT.splits[d])) ss[d][k] = SCRIPT.splits[d][k].map(String);
    }
    setBase(sb); setSplits(ss); setGrinds({ ...SCRIPT.grinds }); setBuys(SCRIPT.buys.slice());
    setPickG({ ...SCRIPT.pickG }); setPickW({ ...SCRIPT.pickW });
  };

  function grindCell(r: Row, where: string = "row"): ReactNode {
    const n = grinds[r.id] || 0;
    const pid = pinId(r.id) + "-" + where;
    return (
      <div key={"g" + r.id + where} id={pid} data-pin={pid} ref={attachPin(pid)} style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "nowrap", overflowAnchor: "auto" }}>
        <Button label="−" variant="quiet" disabled={n === 0} onClick={(ev?: any) => press(pid, ev, () => setN(r.id, n - 1))} />
        <span style={{ minWidth: 28, textAlign: "center", flex: "0 0 auto", color: theme.text.primary }}>{n}</span>
        <Button label="+" variant="quiet" onClick={(ev?: any) => press(pid, ev, () => setN(r.id, n + 1))} />
      </div>
    );
  }
  const issueTag = (r: Row) => r.errors.length
    ? <Status key={"i" + r.id} tone="danger">{r.errors[0] + (r.errors.length > 1 ? " (+" + (r.errors.length - 1) + ")" : "")}</Status>
    : <Status key={"i" + r.id} tone="success">OK</Status>;

  // ── inspector data ──
  const modState = (m: Mods, k: string) => (m[k] ? "R" + m[k][0] + " tier · " + m[k][1].toFixed(1) + " / " + C.CEIL[m[k][0] - 1] : "not owned");
  const shopLabel = (k: string) => {
    const m = cur.mods[k];
    const act = !m ? "buy at the R" + (cur.rnd + 1) + " tier" : m[0] >= cur.rnd + 1 ? "already R" + (cur.rnd + 1) + " tier" : "upgrade R" + m[0] + " → R" + (cur.rnd + 1);
    return k + " · " + MOD_NAME[k] + " · " + act + " · " + money(cur.tierPrice);
  };
  const hereBuys = buys.map((b, i) => ({ b, i })).filter((x) => x.b.at === cur.id);
  const pickOpts = [{ value: "", label: "Not assigned (XP is lost)" }, ...kit.map((k) => ({ value: k, label: k + " · " + MOD_NAME[k] }))];
  const cashMoveRows = cur.moves.map((m) => [
    m.label, m.purse ? money(m.purse) : "—", m.toDebt ? moneyS(-m.toDebt) : "—", m.label === "On arrival" ? "—" : moneyS(m.net), money(m.cash), money(m.debt),
  ]);
  const modRows = kit.map((k) => {
    const sp = splits[cur.d][k];
    const iss = splitIssue(k, sp);
    const pid = pinId("split-" + cur.d + "-" + k);
    return [
      k + " · " + MOD_NAME[k],
      modState(cur.modsRace, k),
      modState(cur.mods, k),
      ...[0, 1, 2].map((i) => (
        <div key={k + i} id={pid + "-" + i} data-pin={pid + "-" + i} ref={attachPin(pid + "-" + i)} style={{ minWidth: 70, overflowAnchor: "auto" }}>
          <Input type="number" value={sp ? sp[i] : ""} placeholder="%" onChange={(v: string) => setS(cur.d, k, i, v)} />
        </div>
      )),
      iss ? <Status key={"s" + k} tone={cur.modsRace[k] && cur.modsRace[k][1] > 0 ? "danger" : "neutral"}>{iss}</Status> : <Status key={"s" + k} tone="success">Valid</Status>,
    ];
  });
  const st = cur.stats;
  const tot = st ? st[0] + st[1] + st[2] : 0;
  const tune = C.TUNE[cur.d] as number[];
  const buildText = st
    ? STATN.map((n, i) => n + " " + Math.round(st[i]) + " (" + (100 * st[i] / tot).toFixed(1) + "%, tune " + Math.round(100 * tune[i]) + "%)").join(" · ")
    : "Not valid yet: see the issues below";

  // ── campaign data ──
  const valid = rows.filter((r) => r.show !== null);
  const allValid = valid.length === rows.length;
  const low = valid.length ? valid.reduce((m, r) => ((r.show as number) < (m.show as number) ? r : m), valid[0]) : null;
  const bosses = rows.filter((r) => r.boss);
  const gTot = rows.reduce((s, r) => s + r.grinds, 0);
  const lostTot = rows.reduce((s, r) => s + r.lostG + r.lostW, 0);
  const issues = rows.reduce((s, r) => s + r.errors.length, 0);
  const last = rows[rows.length - 1];

  const raceRows = rows.map((r) => [
    <div key={"b" + r.id} id={pinId("sel-" + r.id)} data-pin={pinId("sel-" + r.id)} ref={attachPin(pinId("sel-" + r.id))} style={{ overflowAnchor: "auto" }}>
      <Button label={raceName(r.id)} variant={r.id === cur.id ? "primary" : "quiet"} onClick={(ev?: any) => press(pinId("sel-" + r.id), ev, () => setSel(r.id))} />
    </div>,
    DNAME[r.d] + " · " + r.T + " turns" + (r.boss ? " · hardest track" : ""),
    grindCell(r),
    r.skill.toFixed(3),
    String(Math.round(r.points)),
    r.power.toFixed(1),
    r.r.toFixed(3),
    r.show === null ? "—" : { text: pc(r.show), tone: toneOf(r.show) },
    money(r.cash),
    money(r.debt),
    issueTag(r),
  ]);

  return (
    <Page
      title="Campaign planner: mod_skill"
      summary="The mod_skill rules: no player levels, and race XP goes into mods you pick. You make every choice: the stock car's base setup, each mod's split, every grind, every buy and where each race's XP goes. The page shows power, cash and win chance for R1 to R3, on one standard reading curve. Draft: Barry's mod-skill-v1 study, not the live sim."
      width="wide"
    >
      <Section heading="Setup" actions={<Button label="Reset" onClick={(ev?: any) => press("pin-setup", ev, reset)} />}>
        <div id="pin-setup" data-pin="pin-setup" ref={attachPin("pin-setup")} style={{ overflowAnchor: "auto" }}>
          <Table
            columns={["Base setup at Reiko's (3,000 points)", "POW", "HAN", "EN", "Check"]}
            rows={(C.ROUNDS as string[]).map((d) => {
              const iss = baseIssue(base[d]);
              return [
                DNAME[d] + " (R" + ((C.ROUNDS as string[]).indexOf(d) + 1) + ")",
                ...[0, 1, 2].map((i) => (
                  <div key={d + i} id={"pin-base-" + d + i} data-pin={"pin-base-" + d + i} ref={attachPin("pin-base-" + d + i)} style={{ minWidth: 90, overflowAnchor: "auto" }}>
                    <Input type="number" value={base[d][i]} placeholder="750–1500" onChange={(v: string) => setB(d, i, v)} />
                  </div>
                )),
                iss ? <Status key={"bs" + d} tone="danger">{iss}</Status> : <Status key={"bs" + d} tone="success">Valid</Status>,
              ];
            })}
          />
          <Text>The stock car's 3,000 points (2,400 base plus 4 stock parts) never grow. You set them per district, with each stat at 750–1,500. Nothing is filled in for you, and invalid entries are flagged, not fixed.</Text>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 8 }}>
            <Button label="Load the verified example playthrough" onClick={(ev?: any) => press("pin-setup", ev, loadExample)} />
            <Button label="Reset" onClick={(ev?: any) => press("pin-setup", ev, reset)} />
          </div>
        </div>
      </Section>

      <Section heading={"Race inspector: " + raceName(cur.id)} id="race-inspector">
        <div id="pin-inspector" data-pin="pin-inspector" ref={attachPin("pin-inspector")} style={{ overflowAnchor: "auto" }}>
          <div id="pin-inspector-nav" data-pin="pin-inspector-nav" ref={attachPin("pin-inspector-nav")} style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "flex-end", overflowAnchor: "auto" }}>
            <Button label="← Previous" disabled={idx === 0} onClick={(ev?: any) => press("pin-inspector-nav", ev, () => go(idx - 1))} />
            <Select label="Race" options={rows.map((r) => ({ value: r.id, label: raceName(r.id) }))} value={cur.id} onChange={(v: string) => setSel(v)} />
            <Button label="Next →" disabled={idx === rows.length - 1} onClick={(ev?: any) => press("pin-inspector-nav", ev, () => go(idx + 1))} />
          </div>
          <div style={{ marginTop: 16 }}>
            <Metrics
              metrics={[
                { value: pc(cur.show), label: "Win chance", detail: cur.win ? "District average " + pc(cur.win.d) + (cur.win.h !== null ? ", hardest track " + pc(cur.win.h) : "") : "Fix the issues below", tone: cur.show === null ? "danger" : toneOf(cur.show) },
                { value: cur.skill.toFixed(3), label: "Reading skill (read-only)", detail: "Standard curve: race " + (Math.round((cur.skill - 0.6) / 0.2 * cur.N) + 1) + " of " + (cur.N + 1) + " in " + DNAME[cur.d] },
                { value: cur.power.toFixed(1), label: "Combat power", detail: Math.round(cur.points) + " points / 10 · cap " + C.CAP_POWER[cur.rnd].toFixed(1) },
                { value: cur.r.toFixed(3), label: "r (power / budget)", detail: "Opponent budget " + cur.B.toFixed(1) + " · " + cur.T + " turns" },
              ]}
            />
          </div>
          <div id="pin-inspector-grinds" data-pin="pin-inspector-grinds" ref={attachPin("pin-inspector-grinds")} style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center", overflowAnchor: "auto", marginTop: 16 }}>
            <span style={{ color: theme.text.primary }}>Grinds before this race (− / +)</span>
            {grindCell(cur, "insp")}
            <span style={{ color: theme.text.secondary }}>{"Each pays " + money(purseOf(cur.rnd, "kid", true)) + " and " + C.GRIND_XP[cur.rnd] + " XP"}</span>
          </div>
          <div id="pin-inspector-cash" data-pin="pin-inspector-cash" ref={attachPin("pin-inspector-cash")} style={{ overflowAnchor: "auto", marginTop: 16 }}>
            <Table columns={["Cash pool at this stop", "Purse", "To Sabine (debt)", "Net", "Cash", "Debt left"]} rows={cashMoveRows} align={["start", "end", "end", "end", "end", "end"]} />
            <Text>Order at each stop: buys before grinds, then grinds, then the race, then the story purse and buys after the win, then the race's XP. While the $16,000 debt is open, 65% of each purse goes to Sabine.</Text>
          </div>
          <Grid columns={2}>
            <div id="pin-inspector-shop" data-pin="pin-inspector-shop" ref={attachPin("pin-inspector-shop")} style={{ display: "flex", flexDirection: "column", gap: 12, overflowAnchor: "auto" }}>
              <Text>{"Reiko's shop · " + DNAME[cur.d] + " kit " + kit.join(" ")}</Text>
              <Select label="Mod" options={kit.map((k) => ({ value: k, label: shopLabel(k) }))} value={kit.indexOf(shopKey) >= 0 ? shopKey : kit[0]} onChange={(v: string) => setShopKey(v)} />
              <Segmented options={[{ value: "pre", label: "Before grinds" }, { value: "post", label: "After the win" }]} value={shopPhase} onChange={(v: string) => setShopPhase(v)} />
              <Text>{"Cash on arrival " + money(cur.cashArrive) + " · price " + money(cur.tierPrice) + (cur.rnd > 0 ? " (wholesale −20%)" : "")}</Text>
              <Button label="Add buy" variant="primary" onClick={(ev?: any) => press("pin-inspector-shop", ev, () => setBuys([...buys, { at: cur.id, phase: shopPhase === "pre" ? "pre" : "post", key: kit.indexOf(shopKey) >= 0 ? shopKey : kit[0] }]))} />
              {hereBuys.length ? (
                <Table
                  columns={["Your buys here", ""]}
                  rows={hereBuys.map(({ b, i }) => [b.key + " · " + MOD_NAME[b.key] + " · " + (b.phase === "pre" ? "before grinds" : "after the win"), <Button key={"x" + i} label="Remove" variant="quiet" onClick={(ev?: any) => press("pin-inspector-shop", ev, () => setBuys(buys.filter((_, q) => q !== i)))} />])}
                />
              ) : null}
            </div>
            <div id="pin-inspector-xp" data-pin="pin-inspector-xp" ref={attachPin("pin-inspector-xp")} style={{ display: "flex", flexDirection: "column", gap: 12, overflowAnchor: "auto" }}>
              <Text>XP to a mod. If the mod you pick is full, the rest spills to this district's other owned mods in slot order. Anything left after that is lost.</Text>
              <Select label={"Grind XP (" + cur.grinds + " × " + C.GRIND_XP[cur.rnd] + " = " + cur.xpG.toFixed(0) + ") goes to"} options={pickOpts} value={pickG[cur.id] || ""} onChange={(v: string) => { const o = { ...pickG }; if (v) o[cur.id] = v; else delete o[cur.id]; setPickG(o); }} />
              <Select label={"Win XP (" + cur.xpW.toFixed(1) + ") goes to"} options={pickOpts} value={pickW[cur.id] || ""} onChange={(v: string) => { const o = { ...pickW }; if (v) o[cur.id] = v; else delete o[cur.id]; setPickW(o); }} />
              <Text>{"Lost past ceilings here: grinds " + cur.lostG.toFixed(1) + ", win " + cur.lostW.toFixed(1)}</Text>
            </div>
          </Grid>
          <div style={{ marginTop: 16 }}>
            <Table columns={["Mod (" + DNAME[cur.d] + " split)", "At the race", "After this race's XP", "POW %", "HAN %", "EN %", "Split check"]} rows={modRows} />
            <Text>{"Splits apply to every race in " + DNAME[cur.d] + ". At least 60% must go to the mod's own stat, and the three must add to 100%. Build at this race: " + buildText + "."}</Text>
          </div>
          {cur.errors.length ? <Callout tone="danger" lead="Issues at this race">{cur.errors.join(" · ")}</Callout> : null}
        </div>
      </Section>

      <Section heading="Race by race" id="race-by-race" caption="State on arrival at each race, after its buys before grinds and its grinds. Win chance uses the hardest track where the sim has one (bosses, and every Touge race), otherwise the district average. Cash and debt are after the win, the buys after it and the XP.">
        <Table columns={["Race", "District · length", "Grinds (− / +)", "Skill", "Points", "Power", "r", "Win", "Cash", "Debt", "Issues"]} rows={raceRows} align={["start", "start", "start", "end", "end", "end", "end", "end", "end", "end", "start"]} />
      </Section>

      <Section heading="Standard reading curve" caption="Read-only placeholder. In each district, read skill and QTE timing both start at 0.600 and climb in a straight line with races run there, grinds included, to 0.800 at the boss.">
        <div style={{ overflowAnchor: "none" }}>
          <LineChart points={rows.map((r) => ({ label: r.id, value: r.skill }))} ceiling={0.8} floor={0.6} format={(v: number) => v.toFixed(3)} labels={["Reading skill at each story race"]} />
        </div>
      </Section>

      <Section heading="Campaign at a glance">
        <div style={{ overflowAnchor: "none" }}>
          <Metrics
            metrics={[
              { value: low ? pc(low.show) : "—", label: "Lowest race", detail: low ? raceName(low.id) + (allValid ? "" : " (valid races only)") : "No race has a valid build yet", tone: low ? toneOf(low.show as number) : "danger" },
              { value: bosses.map((r) => pc(r.show)).join(" / "), label: "Bosses R1 / R2 / R3" },
              { value: String(gTot), label: "Grind races", detail: "All added by you" },
              { value: money(last.cash), label: "Cash after the R3 boss", detail: last.debt > 0 ? "Debt left " + money(last.debt) : "Debt cleared" },
              { value: lostTot.toFixed(0), label: "XP lost", detail: "Unassigned, or past every ceiling" },
              { value: String(issues), label: "Open issues", detail: issues ? "See the Issues column" : "Every race is valid", tone: issues ? "danger" : "success" },
            ]}
          />
          {allValid ? <LineChart points={rows.map((r) => ({ label: r.id, value: r.show as number }))} ceiling={100} floor={0} unit="%" labels={["Win chance per story race"]} /> : null}
        </div>
      </Section>

      <Section heading="Rules used" collapsible defaultOpen={false}>
        <Rows
          rows={[
            { title: "Car", detail: "No player levels. The car is the 3,000-point stock car plus each slot's earned mod points. Power = points / 10, capped at 353.1 / 404.2 / 462.5, which is today's level-cap power. The base 3,000 never grows; you set its split per district (750–1,500 per stat)." },
            { title: "Mods", detail: "One mod per stat slot. Street kit P1 P2 H1 E1; Wangan and Touge kit P1 H1 E1 E2 (Touge uses the PHEE pattern). A new mod starts at 0 earned points. Its ceiling is the tier you bought: R1 133, R2 261, R3 407 points. Buying the next tier raises the ceiling and keeps the points. The tier unlocks at round start." },
            { title: "Prices", detail: "Mk1 list per tier: $150 (R1), $700 (R2), $1,200 (R3), with −20% wholesale in R2 and R3. Mods are bought only when you add a buy. A buy you can't afford, or one already at that tier, is flagged and not applied." },
            { title: "Point split", detail: "Each mod's points split across POW / HAN / EN, with at least 60% on its own stat, re-assignable for free. The whole car must stay at 25–50% per stat. Win chance adds the sim's off-tune adjustment for the POW share." },
            { title: "XP", detail: "Story XP per race (Kid 1 … Boss): R1 145.0 / 115.8 / 26.9 / 25.1 / 27.0 / 26.8 / 154.3; R2 96.6 / 72.1 / 67.9 / 60.1 / 29.5 / 30.6 / 92.2; R3 99.6 / 102.3 / 52.2 / 69.5 / 69.6 / 35.0 / 70.5. A grind win is 13 / 15 / 14. Catch-up: entering a round below the last cap adds 75% of the shortfall, split Kid 1 40% / Kid 2 40% / Mature 1 20%. Overflow spills to the next owned mod in slot order; the rest is lost." },
            { title: "Cash", detail: "Wild $1,000, crew $2,500, boss $8,000 × 1 / 1.15 / 1.35 by round; grinds pay 55% of a wild purse. 65% of every purse repays the $16,000 debt until it is cleared. Every race and grind is assumed won." },
            { title: "Win chance", detail: "The sim's live win tables (5 tracks per district, linear in r), blended by the reading curve between the 60/60, 60/80, 80/60 and 80/80 tables. Bosses and Touge show the hardest track. Pre-finale arc and finale are not modelled for mod_skill yet." },
          ]}
        />
      </Section>

      <Section heading="Verified against the Python model">
        <Table
          columns={["Scripted playthrough, 21 races", "Worst difference", ""]}
          rows={[
            ["Car points", ver.worstPts.toFixed(2), <Status key="v1" tone={ver.worstPts < 0.051 ? "success" : "danger"}>{ver.worstPts < 0.051 ? "match" : "off"}</Status>],
            ["r", ver.worstR.toFixed(5), <Status key="v2" tone={ver.worstR < 0.00006 ? "success" : "danger"}>{ver.worstR < 0.00006 ? "match" : "off"}</Status>],
            ["Win chance (pp)", ver.worstWin.toFixed(2), <Status key="v3" tone={ver.worstWin < 0.051 ? "success" : "danger"}>{ver.worstWin < 0.051 ? "match" : "off"}</Status>],
            ["Cash and debt ($)", ver.worstCash.toFixed(2), <Status key="v4" tone={ver.worstCash < 0.006 ? "success" : "danger"}>{ver.worstCash < 0.006 ? "match" : "off"}</Status>],
            ["Races matching on every field", ver.same + " of " + ver.n, <Status key="v5" tone={ver.same === ver.n ? "success" : "danger"}>{ver.same === ver.n ? "all" : "check"}</Status>],
          ]}
        />
        <Text>This page reruns the example playthrough with its own engine and compares it with the Python model, unapproved/barry/mod-skill-v1/planner/py_reference.py, which uses the live sim's win functions. The offline check, verify.mjs, compares 543 numbers over that playthrough plus an error-path plan: all 543 match exactly, and the validation messages match too. The playthrough includes deliberate mistakes (an unaffordable buy, a duplicate buy, an unassigned win XP) to exercise the issue checks.</Text>
      </Section>
    </Page>
  );
}


